insert into control (id, code, domain, title, description) values
    (1, 'IAM-01', 'Identity and access', 'Multi-factor authentication', 'Users must pass multi-factor authentication for remote access, administrative access, and any access to production or sensitive data environments.'),
    (2, 'IAM-02', 'Identity and access', 'Approved access provisioning', 'Access is granted only through an approved request, and permissions are limited to what the user''s role needs.'),
    (3, 'IAM-03', 'Identity and access', 'Periodic access reviews', 'System owners review user and service account access at least every six months and remove any access that is no longer needed.'),
    (4, 'IAM-04', 'Identity and access', 'Access removal at termination', 'All system access for departing employees and contractors is revoked no later than their last working day.'),
    (5, 'DP-01', 'Data protection', 'Encryption at rest', 'Databases, storage, and backups that hold sensitive data are encrypted at rest with strong algorithms and managed keys.'),
    (6, 'DP-02', 'Data protection', 'Encryption in transit', 'Sensitive data sent over public or untrusted networks is protected with current TLS versions, and insecure protocols are disabled.'),
    (7, 'DP-03', 'Data protection', 'Secure data disposal', 'Sensitive data is deleted when its retention period ends, and media or devices that held it are wiped or destroyed before disposal or reuse.'),
    (8, 'LOG-01', 'Logging and monitoring', 'Centralized audit logging', 'Systems that store or process sensitive data log security events such as logins, administrative actions, and data access to a central store kept for at least 12 months.'),
    (9, 'LOG-02', 'Logging and monitoring', 'Daily security log review', 'Security logs and login activity are reviewed daily with automated alerting, and suspicious events are escalated for investigation.'),
    (10, 'CHG-01', 'Change management', 'Approved and tested changes', 'Production changes are documented, assessed for security impact, tested, and approved before release, with a rollback plan.'),
    (11, 'CHG-02', 'Change management', 'Peer code review', 'Every code change is reviewed for quality and security flaws by someone other than the author before it is merged and released.'),
    (12, 'VUL-01', 'Vulnerability management', 'Vulnerability scanning', 'Internal and external vulnerability scans run at least quarterly, and high and critical findings are fixed and confirmed by a rescan.'),
    (13, 'VUL-02', 'Vulnerability management', 'Security patching', 'Security patches are applied within defined timeframes based on severity, with critical patches installed within 30 days of release.'),
    (14, 'VUL-03', 'Vulnerability management', 'Malware protection', 'Servers and endpoints at risk from malware run anti-malware or EDR software that updates automatically and alerts on detections.'),
    (15, 'IR-01', 'Incident response', 'Incident response plan', 'A documented incident response plan sets roles, triage, containment, notification, and post-incident review steps, and it is reviewed and tested at least annually.'),
    (16, 'BC-01', 'Business continuity', 'Continuity and recovery plan', 'A business continuity and disaster recovery plan sets recovery objectives for critical systems and is tested at least annually, with results documented.'),
    (17, 'BC-02', 'Business continuity', 'Data backups', 'Critical data is backed up automatically on a set schedule to storage separate from production, and restores are tested periodically.'),
    (18, 'VEN-01', 'Vendor risk', 'Vendor risk assessment', 'Vendors that handle sensitive data or affect security are listed in a vendor inventory, assessed before onboarding, and reviewed at least annually.'),
    (19, 'VEN-02', 'Vendor risk', 'Vendor security agreements', 'Contracts with vendors that access sensitive data include security, confidentiality, and breach notification terms, plus a business associate agreement when ePHI is involved.'),
    (20, 'PPL-01', 'People security', 'Pre-hire background checks', 'New hires who will access sensitive systems or data complete a background check before access is granted, where local law allows.'),
    (21, 'PPL-02', 'People security', 'Security awareness training', 'All workers complete security awareness training that covers phishing and social engineering at hire and at least annually, and receive periodic security reminders.'),
    (22, 'GOV-01', 'Governance', 'Information security policy', 'Management approves an information security policy, publishes it to all workers, and reviews and updates it at least annually.'),
    (23, 'GOV-02', 'Governance', 'Annual risk assessment', 'A risk assessment of threats and vulnerabilities to sensitive data is performed at least annually, and each risk is tracked to a treatment decision.'),
    (24, 'GOV-03', 'Governance', 'Named security officer', 'A named security officer is accountable for the security program, and security roles and responsibilities are documented for all staff.');
